-- The shop, as a SAP HANA (a tenant the user SHOP owns, or any schema that is its CURRENT_SCHEMA) would hold it for
-- the HANA tests: the same rows as shop.sqlite, with what HANA can say about itself (an identity column, a comment,
-- a unique constraint, a default, a foreign key, an index, a view). No HANA runs in CI; tests/fixtures/db/hana/ was
-- written by hand to the SYS views' documented shapes, and a real HANA seeded with this re-records it with
-- scripts/record-database.mjs hana <url>. One statement per block.
DROP VIEW ORDER_TOTALS;
DROP TABLE ORDERS;
DROP TABLE CUSTOMERS;
CREATE COLUMN TABLE CUSTOMERS (
  ID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  NAME NVARCHAR(100) NOT NULL,
  EMAIL NVARCHAR(255) UNIQUE,
  SIGNED_UP DATE,
  ACTIVE BOOLEAN DEFAULT TRUE
) COMMENT 'People who have ordered';
COMMENT ON COLUMN CUSTOMERS.EMAIL IS 'Lower case';
CREATE COLUMN TABLE ORDERS (
  ID INTEGER PRIMARY KEY,
  CUSTOMER_ID INTEGER NOT NULL REFERENCES CUSTOMERS (ID),
  TOTAL DECIMAL(10, 2),
  PLACED_AT TIMESTAMP,
  STATUS NVARCHAR(20) DEFAULT 'placed',
  NOTES NVARCHAR(500)
);
CREATE INDEX ORDERS_STATUS ON ORDERS (STATUS);
CREATE VIEW ORDER_TOTALS AS SELECT c.NAME, COUNT(o.ID) AS ORDERS, SUM(o.TOTAL) AS TOTAL FROM CUSTOMERS c LEFT JOIN ORDERS o ON o.CUSTOMER_ID = c.ID GROUP BY c.NAME;
